import{_ as n,C as r,o as s,c as d,j as a,a as t,E as i,a2 as l}from"./chunks/framework.Di-jvWLj.js";const k=JSON.parse('{"title":"Docker Image","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/docker.md","filePath":"deployment/docker.md","lastUpdated":1792501536000}'),c={name:"deployment/docker.md"},g={id:"docker-image",tabindex:"-1"};function m(p,e,u,h,b,f){const o=r("Badge");return s(),d("div",null,[a("h1",g,[e[0]||(e[0]=t("Docker Image ",-1)),i(o,{type:"warning",text:"Planned"}),e[1]||(e[1]=t()),e[2]||(e[2]=a("a",{class:"header-anchor",href:"#docker-image","aria-label":'Permalink to "Docker Image <Badge type="warning" text="Planned" />"'},"​",-1))]),e[3]||(e[3]=l('<div class="warning custom-block"><p class="custom-block-title">Planned</p><p>Neither the base image nor the CLI build command exists yet.</p></div><h2 id="base-image" tabindex="-1">Base image <a class="header-anchor" href="#base-image" aria-label="Permalink to &quot;Base image&quot;">​</a></h2><p>A base runtime image, planned as <code>ghcr.io/chamberu/node</code>: Node 24, slim or distroless, running as a non-root user. It is built for several architectures and referenced by digest from the template repository.</p><h2 id="agent-images" tabindex="-1">Agent images <a class="header-anchor" href="#agent-images" aria-label="Permalink to &quot;Agent images&quot;">​</a></h2><p>Agent repositories use a two-stage Dockerfile from the template:</p><ol><li><strong>Build stage:</strong> install dependencies and bundle the app entry with <code>chamberu build</code>.</li><li><strong>Runtime stage:</strong> copy the bundle onto the base image and start it with an exec-form <code>CMD</code>, so <code>SIGTERM</code> reaches Node directly and the engine can <a href="/guide/recovery#drain">drain</a>.</li></ol><p>The same image serves every mode: the long-running app, and a one-shot <code>chamberu run-job &lt;agent&gt; &lt;trigger&gt;</code> for clusters that prefer Kubernetes CronJobs over in-process scheduling.</p><h2 id="tags-for-flux" tabindex="-1">Tags for Flux <a class="header-anchor" href="#tags-for-flux" aria-label="Permalink to &quot;Tags for Flux&quot;">​</a></h2><p>The template&#39;s CI pushes images tagged <code>main-&lt;sha&gt;-&lt;unix timestamp&gt;</code> for every push to the main branch, plus semver tags for releases. Flux image automation picks the newest tag and updates the <code>HelmRelease</code>. See <a href="/deployment/kubernetes">Kubernetes &amp; Flux</a>.</p><h2 id="sandbox-image" tabindex="-1">Sandbox image <a class="header-anchor" href="#sandbox-image" aria-label="Permalink to &quot;Sandbox image&quot;">​</a></h2><p>Agents that run untrusted code (reproducing a bug, running tests) use a separate sandbox image, planned as <code>ghcr.io/chamberu/sandbox-node</code>: Node 24, git and npm, a non-root user and a read-only root filesystem except the workspace. It runs as its own pod, never inside the agent&#39;s container.</p>',11))])}const _=n(c,[["render",m]]);export{k as __pageData,_ as default};
